+		transition func()
+		readiness  int
+		liveness   int
+	}{
+		{"before serving", func() {}, http.StatusServiceUnavailable, http.StatusOK},
+		{"serving", state.markReady, http.StatusOK, http.StatusOK},
+		{"draining", state.markDraining, http.StatusServiceUnavailable, http.StatusOK},
