		}
	}
	return fleetActionWire{
		ID: base64.RawURLEncoding.EncodeToString(record.ID), Version: record.Version, State: record.State,
		AgentID: encodeFleetID(record.AgentID), AgentGeneration: record.AgentGeneration,
